import { useState, useEffect } from 'react';

interface Todo {
  id: number;
  title: string;
  completed: boolean;
}

export default function TodoCrudAutocomplete() {
  const [todos, setTodos] = useState<Todo[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [newTitle, setNewTitle] = useState('');
  const [searchQuery, setSearchQuery] = useState('');

  const loadTodos = async () => {
    setLoading(true);
    setError(null);
    try {
      const res = await fetch('http://localhost:4000/api/todos');
      if (!res.ok) {
        throw new Error('Failed to load todos');
      }
      const data = (await res.json()) as Todo[];
      setTodos(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadTodos();
  }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    const trimmed = newTitle.trim();
    if (!trimmed) return;

    try {
      const res = await fetch('http://localhost:4000/api/todos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ title: trimmed }),
      });
      if (!res.ok) {
        throw new Error('Failed to create todo');
      }
      const created = (await res.json()) as Todo;
      setTodos(prev => [...prev, created]);
      setNewTitle('');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    }
  };

  const toggleTodo = async (todo: Todo) => {
    try {
      const res = await fetch(`http://localhost:4000/api/todos/${todo.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ completed: !todo.completed }),
      });
      if (!res.ok) {
        throw new Error('Failed to update todo');
      }
      const updated = (await res.json()) as Todo;
      setTodos(prev => prev.map(t => (t.id === updated.id ? updated : t)));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    }
  };

  const deleteTodo = async (id: number) => {
    try {
      const res = await fetch(`http://localhost:4000/api/todos/${id}`, { method: 'DELETE' });
      if (!res.ok) {
        throw new Error('Failed to delete todo');
      }
      setTodos(prev => prev.filter(t => t.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Unknown error');
    }
  };

  const trimmedQuery = searchQuery.trim();
  const suggestions = trimmedQuery
    ? todos.filter(todo =>
        todo.title.toLowerCase().includes(trimmedQuery.toLowerCase())
      )
    : [];

  if (loading) {
    return (
      <div className="todo-crud-autocomplete loading">
        Loading todos...
      </div>
    );
  }

  return (
    <div className="todo-crud-autocomplete">
      <h1>Todo CRUD with Autocomplete</h1>

      {error && (
        <div className="error-banner">Error: {error}</div>
      )}

      <form onSubmit={handleAdd} className="add-form">
        <input
          type="text"
          placeholder="New todo title..."
          value={newTitle}
          onChange={e => setNewTitle(e.currentTarget.value)}
        />
        <button type="submit">Add</button>
      </form>

      <div className="search">
        <input
          type="text"
          placeholder="Search todos..."
          value={searchQuery}
          onChange={e => setSearchQuery(e.currentTarget.value)}
        />
        {trimmedQuery && (
          suggestions.length === 0 ? (
            <div className="status empty">No matches found.</div>
          ) : (
            <ul className="suggestions">
              {suggestions.map(todo => (
                <li key={todo.id} className="suggestion-item">
                  {todo.title}
                </li>
              ))}
            </ul>
          )
        )}
      </div>

      <ul className="todo-list">
        {todos.map(todo => (
          <li key={todo.id} className="todo-item">
            <label>
              <input
                type="checkbox"
                checked={todo.completed}
                onChange={() => toggleTodo(todo)}
              />
              <span className={todo.completed ? 'completed' : ''}>
                {todo.title}
              </span>
            </label>
            <button onClick={() => deleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}
